        /// <summary>
        /// Configures the HttpClients.
        /// </summary>
        /// <param name="client"></param>
        /// <param name="builder"></param>
        /// <returns></returns>
        public HostConfiguration AddApiHttpClients
        (
            Action<HttpClient>? client = null, Action<IHttpClientBuilder>? builder = null)
        {
            if (client == null)
                client = c => c.BaseAddress = new Uri(ClientUtils.BASE_ADDRESS);

            List<IHttpClientBuilder> builders = new List<IHttpClientBuilder>();

            builders.Add(_services.AddHttpClient<IGlobalCustomerApi, GlobalCustomerApi>(client));
            builders.Add(_services.AddHttpClient<IGlobalEzmaxclientApi, GlobalEzmaxclientApi>(client));
            builders.Add(_services.AddHttpClient<IGlobalEzmaxcustomerApi, GlobalEzmaxcustomerApi>(client));
            builders.Add(_services.AddHttpClient<IModuleReportApi, ModuleReportApi>(client));
            builders.Add(_services.AddHttpClient<IModuleUserApi, ModuleUserApi>(client));
            builders.Add(_services.AddHttpClient<IObjectActivesessionApi, ObjectActivesessionApi>(client));
